def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if not isinstance(nanoseconds, int):
        raise TypeError("nanoseconds must be an integer")
    if tz is not None and not isinstance(tz, datetime.timezone):
        raise TypeError("tz must be a datetime.timezone object")
    return Time(nanoseconds // 1000000000, nanoseconds % 1000000000, tz)

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if isinstance(value, datetime.time):
        return value.isoformat()
    elif isinstance(value, datetime.datetime):
        return value.time().isoformat()
    else:
        raise ValueError("Invalid type for time dehydration")

