def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.
    """

    # Check if name is a valid class name
    if not name.isidentifier():
        raise ValueError("Name is not a valid identifier")

    # Check if fields is a list or tuple of field names
    if not isinstance(fields, (list, tuple)):
        raise ValueError("Fields must be a list or tuple of field names")

    # Check if srid_map is a dictionary
    if not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a dictionary")

    # Create a new Point class with the given name and fields
    class Point:
        __slots__ = fields

        def __init__(self, *args, **kwargs):
            for i, field in enumerate(fields):
                value = args[i] if i < len(args) else kwargs.get(field, None)
                setattr(self, field, value)

        def __repr__(self):
            return f"{name}({', '.join(getattr(self, field) for field in fields)})"

        @classmethod
        def from_wkb(cls, srid, wkb):
            point = cls()
            for field in fields:
                setattr(point, field, srid_map[srid].from_wkb(wkb))
            return point

        @classmethod
        def from_wkt(cls, srid, wkt):
            point = cls()
            for field in fields:
                setattr(point, field, srid_map[srid].from_wkt(wkt))
            return point

    return Point

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Examples:
        >>> @deprecated("'foo' has been deprecated in favour of 'bar'")
        ... def foo(x):
        ...     pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    from itertools import count
    cnt = count()
    result = []
    for s in seq:
        result.append(s)
        next(cnt)
    for i, s in enumerate(result):
        if i % 2 == 0:
            result.append(result.pop(i+1))
    return result

def cached(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            now = timer()
            try:
                value, last_update = cache[args]
                if now - last_update > ttl:
                    raise KeyError
            except KeyError:
                value = func(*args, **kwargs)
                cache[args] = (value, now)
            return value
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer or None')
    if maxsize is not None and maxsize <= 0:
        raise ValueError('maxsize must be a positive integer or None')

    def decorator(func):
        cache = {}
        keys = deque()
        lock = RLock()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, kwargs) if typed else args
            with lock:
                if key in cache:
                    keys.remove(key)
                elif len(keys) == maxsize:
                    cache.pop(keys.popleft())
                keys.append(key)
                cache[key] = func(*args, **kwargs)
            return cache[key]

        wrapper.cache = cache
        wrapper.keys = keys
        wrapper.lock = lock
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(fn):
        if maxsize is None:
            return fn
        if typed is None:
            typed = False
        cache = OrderedDict()
        lock = Lock()

        def wrapper(*args, **kwargs):
            k = (args, kwargs) if typed else args
            with lock:
                if k in cache:
                    cache.move_to_end(k)
                    return cache[k]
                else:
                    v = fn(*args, **kwargs)
                    cache[k] = v
                    if len(cache) > maxsize:
                        cache.popitem(last=False)
                    return v
        return wrapper

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        cache = {}
        use_count = defaultdict(int)
        use_total = defaultdict(int)
        use_order = deque()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            if key in use_order:
                use_order.remove(key)
            use_count[key] += 1
            use_total[key] += 1
            use_order.appendleft(key)
            if len(use_order) > maxsize:
                cache.pop(use_order.pop(), None)
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            return cache[key]

        def clear():
            cache.clear()
            use_count.clear()
            use_total.clear()
            use_order.clear()

        wrapper.clear = clear
        return wrapper

