def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces:
        return None

    # Determine the renderer to use based on the style
    renderer = _get_version_renderer(style)

    if renderer is None:
        return None

    config = get_definition_from_renderer(renderer)

    # Render the version pieces using the renderer
    return renderer.render(pieces, config)

def _get_version_renderer(style):
    """Return the renderer for the given style."""

    if style == "UNIQUE":
        return UniqueValuesRenderer()
    elif style == "STRETCHED":
        return StretchedRenderer()
    elif style == "CLASSIFIED":
        return ClassifiedRenderer()
    else:
        return None

def get_definition_from_renderer(renderer):
    """Return a dictionary definition of the given renderer."""

    config = {
        'colors': [(x[0], x[1].to_hex()) for x in renderer.colormap],
        'options': {}
    }

    if renderer.fill_value:
        config['options']['fill_value'] = renderer.fill_value

    if isinstance(renderer, StretchedRenderer):
        config['type'] = 'stretched'
        config['options']['color_space'] = renderer.colorspace
    elif isinstance(renderer, UniqueValuesRenderer):
        config['type'] = 'unique'
        if renderer.labels:
            config['options']['labels'] = renderer.labels
    elif isinstance(renderer, ClassifiedRenderer):
        config['type'] = 'classified'
    else:
        raise ValueError('{0} is not a valid renderer type'.format(renderer.__class__.__name__))

    return config

