def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        current_version = version.split(".")
        if len(current_version) == 1:
            return f"{int(current_version[0]) + 1}"
        elif len(current_version) == 2:
            return f"{int(current_version[0]) + 1}.0"
        else:
            return f"{int(current_version[0]) + 1}.{int(current_version[1]) + 1}"
    except ValueError as e:
        raise ValueError(f"Invalid version format: {version}") from e

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.
    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.
    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    try:
        # Check if each version directory has an inventory file
        for version in version_dirs:
            inventory_path = os.path.join(version, 'inventory.json')
            if not os.path.exists(inventory_path):
                raise ValueError(f'Missing inventory for version {version}')

            # Check if the inventory contains a content digest different from the root inventory
            with open(inventory_path, 'r') as f:
                inventory = json.load(f)
                for file_name, digest in inventory['digests'].items():
                    if digest != self.root_inventory['digests'].get(file_name):
                        self.differing_digests[file_name] = digest
    except (FileNotFoundError, ValueError) as e:
        raise ValueError(f'Error validating version inventories: {e}')

