def deep_merge_nodes(nodes):
    result = []
    keys = set()
    for key, value in nodes:
        if key not in keys:
            result.append((key, value))
            keys.add(key)
        else:
            for i, (k, v) in enumerate(result):
                if k == key:
                    if isinstance(v, ruamel.yaml.nodes.MappingNode):
                        result[i] = (key, deep_merge_nodes([(k, v), (key, value)]))
                    else:
                        result[i] = (key, value)
                    break
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        option_strings = action.option_strings
        if option_strings:
            flags.append(option_strings[0])
    return " ".join(flags)

def deep_merge_nodes(nodes):
    # Create a dictionary to hold the merged node values
    merged_nodes = {}

    # Iterate over the list of nodes
    for node in nodes:
        # Get the key and value from the current node
        key, value = node

        # If the key is not in the dictionary, add it and its value
