    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Get the explicit metaclass, if any.
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("__metaclass__ must be a type, got %r" % (explicit_mc,))

    # Check if any of the bases have a __metaclass__ attribute.
    metaclasses = [type(base) for base in bases]
    metaclass = metaclasses[0]

    # Check if there are multiple metaclasses.
    if len(metaclasses) > 1:
        # If there are multiple metaclasses, check if one is a subclass of the
        # others.
        for metaclass2 in metaclasses[1:]:
            if issubclass(metaclass2, metaclass):
                continue
            elif issubclass(metaclass, metaclass2):
                metaclass = metaclass2
            else:
                raise TypeError("Inconsistent metaclasses in %r" % (bases,))

    # Check if the explicit metaclass is a subclass of the deduced metaclass.
    if explicit_mc is not None and not issubclass(explicit_mc, metaclass):
        raise TypeError("__metaclass__ must be a subclass of %r" % (metaclass,))

    # Return the metaclass.
    return metaclass

