    if spec_content is None:
        raise IRValidatorException("spec_content is missing")

    try:
        spec_dict = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Unable to parse spec content: {e}")

    mandatory_fields = ['name', 'type', 'version']
    for field in mandatory_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"'{field}' field is missing in spec file")

    return spec_dict

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except OSError:
        raise IRValidatorException(f"Could not open file {yaml_file}")
    except yaml.YAMLError:
        raise IRValidatorException(f"Could not load YAML data from {yaml_file}")

    try:
        cls.validate(data)
    except IRValidatorException:
        raise IRValidatorException(f"File {yaml_file} has missing or invalid fields")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        include_spec = parser_dict['include']
        if isinstance(include_spec, six.string_types):
            include_spec = {'behavior': include_spec}
        include_behavior = include_spec['behavior']
        grouped_options = self._parse_section_options(include_spec['options']).unwrap()
        if include_behavior == 'extend':
            parser_dict['options'] = parser_dict.get('options', []) + grouped_options
        elif include_behavior == 'prepend':
            parser_dict['options'] = grouped_options + parser_dict.get('options', [])
        else:
            raise KeyError("Unrecognized include behavior: %s" % include_behavior)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    spec = self.spec
    if spec is None:
        return {}

    defaults = {}
    for arg, value in spec.items():
        if isinstance(value, _BaseOpt):
            # if the value is an option, get the default value from the option.
            if not isinstance(value, NoDefault):
                defaults[arg] = value.default
        elif isinstance(value, dict):
            # if the value is a dict, recursively get the defaults for the dict.
            b = get_spec_defaults(value)
            if b:
                defaults[arg] = b
        else:
            # else, use the value as is.
            defaults[arg] = value

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """

    dep_args = {}
    for arg in self.args:
        if arg.deprecated_options:
            for deprecated_option in arg.deprecated_options:
                dep_args[deprecated_option] = arg.name
    return dep_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    for cli_arg, answer_file_arg in zip(cli_args, answer_file_args):
        if cli_arg in answer_file_arg and cli_arg not in self.ignore_args:
            warnings.warn(
                "The argument '{}' in the answer file is deprecated and will be removed in a future version.".format(cli_arg),
                DeprecationWarning
            )

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.argspec.args:
        if not arg in args:
            raise Exception("Missing required argument: %s" % arg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            valid_choices = self.choices[arg_name]
            if arg_value not in valid_choices:
                msg = "Invalid choice for argument '{}'. Must be one of the following: {}"
                raise ConfigurationError(arg_name, ', '.join(valid_choices))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check that both minimum and maximum values are provided
    if 'min_value' not in args or 'max_value' not in args:
        raise ValueError("Both minimum and maximum values must be provided")

    # Check that the minimum value is less than or equal to the maximum value
    if args['min_value'] > args['max_value']:
        raise ValueError("Minimum value must be less than or equal to maximum value")

    # Check that the value is between the minimum and maximum values
    if args['value'] < args['min_value'] or args['value'] > args['max_value']:
        raise ValueError("Value must be between minimum and maximum values")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg_name, arg_value in args.items():
        if arg_name in self.controls:
            control_args[arg_name] = arg_value
        elif arg_name in self.nested:
            nested_args[arg_name] = arg_value
        else:
            custom_args[arg_name] = arg_value

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict
        else:
            for key, value in extra_vars.items():
                vars_dict[str(key)] = value
            return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for option in self.options:
        if (
            option.cmd is not None
            and option.cmd == parser_name
            and option.opt.type is not None
        ):
            try:
                values_dict[option.long] = option.opt.type(
                    values_dict[option.long]
                )
            except ValueError:
                raise argparse.ArgumentTypeError(
                    f"Invalid type for: {option.long} expected"
                    f" {option.opt.type.__name__} got {type(values_dict[option.long]).__name__}"
                )

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, 'plugin.json')) as f:
            plugin_spec = json.load(f)
    except FileNotFoundError:
        raise ValueError(f"Plugin spec not found in directory {plugin_dir}")
    except json.JSONDecodeError:
        raise ValueError(f"Invalid plugin spec in directory {plugin_dir}")

    flatten_dict = {}
    for prop, value in plugin_spec.items():
        if isinstance(value, dict):
            for subprop, subvalue in value.items():
                flatten_dict[f"{prop}.{subprop}"] = subvalue
        else:
            flatten_dict[prop] = value

    return flatten_dict

def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        if "config_path" not in os.environ:
            os.environ["config_path"] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
